#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    vector<string> cur(n);
    for (auto &row : cur) cin >> row;

    const int di[8] = {-1,-1,-1,0,0,1,1,1};
    const int dj[8] = {-1,0,1,-1,1,-1,0,1};

    while (q--) {
        vector<string> nxt(n, string(n, '0'));
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cnt = 0;
                for (int k = 0; k < 8; k++) {
                    int ni = i + di[k], nj = j + dj[k];
                    if (ni >= 0 && ni < n && nj >= 0 && nj < n && cur[ni][nj] == '1')
                        cnt++;
                }
                if (cur[i][j] == '1') {
                    nxt[i][j] = (cnt == 2 || cnt == 3) ? '1' : '0';
                } else {
                    nxt[i][j] = (cnt == 3) ? '1' : '0';
                }
            }
        }
        cur = move(nxt);
    }

    for (auto &row : cur) cout << row << '\n';
    return 0;
}
